  color:#b8dcff; text-decoration:none; white-space:nowrap;
}
#webcamPanel .webcam-external a { min-height:44px; padding-inline:14px; border:1px solid #6084ad; background:#243c57; font-weight:650; }
#webcamPanel :is(.webcam-external a,#webcamSourceLink):hover { background:#2a3d57; text-decoration:underline; }
#webcamPanel .webcam-source { display:flex; align-items:center; gap:4px; margin-top:5px; }
#webcamPanel .webcam-source > span { flex:1 1 auto; padding-inline-start:3px; color:#bacade; font-size:11px; }
@media (max-width:900px), (max-width:1366px) and (any-pointer:coarse), (max-height:560px) and (pointer:coarse) {
  #webcamPanel { --webcam-control-size:44px; --webcam-panel-space:calc(100dvh - 205px); --webcam-feed-limit:34dvh; top:85px; width:min(360px,calc(100% - 16px)); }
  #webcamPanel #webcamChoice { font-size:16px !important; }
}
